/**
 * Runtime support for vecDSL programs generated for MongoDB, through the official mongodb driver. Generated by vecDSL 7.
 * Do not edit.
 *
 * Every command document, index definition, filter and aggregation pipeline is built by the generator and arrives here as a
 * value identical in the Python, TypeScript and Java programs; this module sends it with Db.command or Collection.aggregate
 * and shapes the answer. Numbers are sent in one BSON form in every language (integral values as int32, or int64 beyond its
 * range, others as double; vectors always as doubles). Search results are eventually consistent: mongot follows mongod
 * through a change stream, so a write that asks for visibility waits until every search index of its collection shows it. The
 * result-shape clauses that MongoDB has no stage for (boost and mmr, and the result clauses of a hybrid search) run in the shared
 * module vecdslShapes over the candidate window.
 */

import { randomUUID } from "node:crypto";
import { readFileSync } from "node:fs";
import { ClientSession, Decimal128, Document, Double, Long, MongoClient, MongoError, MongoServerError, ObjectId } from "mongodb";
import { shape as shapeCandidates, UnsupportedShape, type Json as Shapeable } from "./vecdslShapes";

export const SDK_PACKAGE = "{{sdk.typescript.package}}";
export const SDK_VERSION = "{{sdk.typescript.version}}";

const DIGITS = 6;
const BATCH = 500;
const POLL_MILLIS = 250;
const INT32 = 2 ** 31;
const STAMP = "vecdsl_stamp";
const VERSION = "vecdsl_version";
const EXPIRES = "vecdsl_expires";

type Json = unknown;
type Doc = Record<string, unknown>;
type Probe = { index: string; kind: string; path?: string; dims?: number };
type Visible = { probes: Probe[]; timeout_seconds: number };
type Bounds = { min?: number; max?: number };

export class UnsupportedFeature extends Error {}

export class MongodbFailure extends Error {}

export function unsupported(vendor: string, feature: string): never {
  throw new UnsupportedFeature(`${feature} is not supported for target ${vendor}`);
}

export function env(name: string): string {
  const value = process.env[name];
  if (value === undefined) {
    throw new Error(`environment variable ${name} is not set`);
  }
  return value;
}

/** The MongoClient of one program; credentials come from the environment only. */
export class Client {
  readonly mongo: MongoClient;

  constructor(readonly url: string, user: string | null, userVariable: string, passwordVariable: string, readonly timeoutSeconds: number) {
    const authority = url.split("//")[1]?.split("/")[0] ?? "";
    if (authority.includes("@")) {
      throw new Error("the MongoDB URI must not contain credentials; set them in the environment");
    }
    const millis = Math.round(timeoutSeconds * 1000);
    const name = process.env[userVariable] || user;
    const options: Record<string, unknown> = { serverSelectionTimeoutMS: millis, connectTimeoutMS: millis, socketTimeoutMS: millis, appName: "vecdsl" };
    if (name) {
      const password = process.env[passwordVariable];
      if (password === undefined) {
        throw new Error(`environment variable ${passwordVariable} is not set (the password of user ${name})`);
      }
      options.auth = { username: name, password };
      options.authSource = "admin";
    }
    this.mongo = new MongoClient(url, options);
  }

  async close(): Promise<void> {
    await this.mongo.close();
  }
}

export async function connect(options: { url: string; user?: string | null; userVariable?: string; passwordVariable?: string; timeoutSeconds?: number }): Promise<Client> {
  return new Client(options.url, options.user ?? null, options.userVariable ?? "VECDSL_MONGODB_USER", options.passwordVariable ?? "VECDSL_MONGODB_PASSWORD",
    options.timeoutSeconds ?? 30);
}

function isPlain(item: unknown): item is Doc {
  return item !== null && typeof item === "object" && Object.getPrototypeOf(item) === Object.prototype;
}

/** A value in the BSON form every runtime sends: integral numbers as int32 (int64 beyond), others as double, {"$date": ISO} as a date. */
function bson(item: Json): Json {
  if (typeof item === "number") {
    if (Number.isInteger(item) && Math.abs(item) < 1e15 && (item < -INT32 || item >= INT32)) {
      return Long.fromNumber(item);
    }
    return item;
  }
  if (Array.isArray(item)) {
    return item.map(bson);
  }
  if (isPlain(item)) {
    const keys = Object.keys(item);
    if (keys.length === 1 && keys[0] === "$date" && typeof item.$date === "string") {
      return parseDate(item.$date);
    }
    return Object.fromEntries(keys.map((key) => [key, bson(item[key])]));
  }
  return item;
}

function parseDate(text: string): Date {
  const date = new Date(/^\d{4}-\d{2}-\d{2}$/.test(text) ? `${text}T00:00:00Z` : text);
  if (Number.isNaN(date.getTime())) {
    throw new MongodbFailure(`not a date: ${text}`);
  }
  return date;
}

function doubles(vector: unknown): unknown {
  return vector === null || vector === undefined ? vector : (vector as number[]).map((item) => new Double(Number(item)));
}

/** GeoJSON points from {"$geoPoint": "lat,lon"} (a geo_point value of the script) and from {lat, lon} records. */
function geo(item: unknown): unknown {
  if (isPlain(item) && Object.keys(item).length === 1 && "$geoPoint" in item) {
    const text = item.$geoPoint;
    const parts = typeof text === "string" ? text.split(",").map(Number) : [];
    if (parts.length !== 2 || parts.some((part) => Number.isNaN(part))) {
      throw new MongodbFailure(`a geo_point value is written "lat,lon", not ${JSON.stringify(text)}`);
    }
    return { type: "Point", coordinates: [new Double(parts[1]), new Double(parts[0])] };
  }
  if (isPlain(item) && "lat" in item && ("lon" in item || "lng" in item)) {
    return { type: "Point", coordinates: [new Double(Number(item.lon ?? item.lng)), new Double(Number(item.lat))] };
  }
  return item;
}

function coerce(document: Doc, vectors?: string[] | null, dates?: string[] | null): Doc {
  const result = bson(document) as Doc;
  for (const name of vectors ?? []) {
    if (result[name] !== null && result[name] !== undefined) {
      result[name] = doubles(result[name]);
    }
  }
  for (const name of dates ?? []) {
    if (typeof result[name] === "string") {
      result[name] = parseDate(result[name] as string);
    }
  }
  for (const name of Object.keys(result)) {
    result[name] = geo(result[name]);
  }
  return result;
}

/**
 * Result values in one form for every host language: floats rounded, integral numbers as integers, dates as ISO strings; without
 * rounded, the numbers as they are (the candidates of the shared result-shape module, which rounds once).
 */
function value(item: Json, rounded = true): Json {
  if (typeof item === "number") {
    return Number.isFinite(item) && rounded ? Number(item.toFixed(DIGITS)) + 0 : item;
  }
  if (item instanceof Long) {
    return item.toNumber();
  }
  if (item instanceof Double) {
    return value(item.valueOf(), rounded);
  }
  if (item instanceof Decimal128) {
    return value(Number.parseFloat(item.toString()), rounded);
  }
  if (item instanceof Date) {
    return item.toISOString();
  }
  if (item instanceof ObjectId) {
    return item.toHexString();
  }
  if (Array.isArray(item)) {
    return item.map((entry) => value(entry, rounded));
  }
  if (item !== null && typeof item === "object") {
    return Object.fromEntries(Object.entries(item as Doc).map(([key, entry]) => [key, value(entry, rounded)]));
  }
  return item;
}

/** A record with the key first and the score second, as every runtime orders them. */
function record(document: Doc, key?: string | null): Doc {
  if (!key || !(key in document)) {
    return document;
  }
  const ordered: Doc = { [key]: document[key] };
  if ("score" in document) {
    ordered.score = document.score;
  }
  for (const [name, item] of Object.entries(document)) {
    if (!(name in ordered)) {
      ordered[name] = item;
    }
  }
  return ordered;
}

function failure(error: unknown, what: string): MongodbFailure {
  if (error instanceof MongoServerError) {
    return new MongodbFailure(`${what} failed: ${error.codeName ?? error.code}: ${error.errmsg ?? error.message}`);
  }
  return new MongodbFailure(`${what} failed (${error instanceof Error ? error.name : "error"}): ${error instanceof Error ? error.message : String(error)}`);
}

async function runCommand(client: Client, database: string, document: Doc, session?: ClientSession): Promise<Document> {
  try {
    return await client.mongo.db(database).command(bson(document) as Document, session ? { session } : {});
  } catch (error) {
    throw failure(error, `${Object.keys(document)[0]} on ${database}`);
  }
}

function select(item: Json, path?: string[] | null): Json {
  let current = item;
  for (const key of path ?? []) {
    if (current === null || current === undefined) {
      return null;
    }
    current = Array.isArray(current) ? (current[Number(key)] ?? null) : ((current as Doc)[key] ?? null);
  }
  return current;
}

/** One database command; select picks a member of the answer, wrap names it, ignore lists error code names that mean done. */
export async function command(client: Client, args: { database: string; command: Doc; select?: string[]; wrap?: string; ignore?: string[] }): Promise<Json> {
  let answer: Document;
  try {
    answer = await client.mongo.db(args.database).command(bson(args.command) as Document);
  } catch (error) {
    if (error instanceof MongoServerError && (args.ignore ?? []).includes(error.codeName ?? "")) {
      return null;
    }
    throw failure(error, `${Object.keys(args.command)[0]} on ${args.database}`);
  }
  const result = value(select(answer, args.select));
  return args.wrap !== undefined ? { [args.wrap]: result } : result;
}

export async function exists(client: Client, args: { database: string; collection: string }): Promise<boolean> {
  const answer = await runCommand(client, args.database, { listCollections: 1, filter: { name: { $eq: args.collection } }, nameOnly: true });
  return (answer.cursor.firstBatch as unknown[]).length > 0;
}

/** The pipeline with every $vectorSearch queryVector as doubles (vector replaces it when given). */
function queryVectors(pipeline: Doc[], vector?: number[]): Doc[] {
  return pipeline.map((stage) => {
    if ("$vectorSearch" in stage) {
      const search = { ...(stage.$vectorSearch as Doc) };
      search.queryVector = doubles(vector ?? search.queryVector);
      return { ...stage, $vectorSearch: search };
    }
    if ("$rankFusion" in stage) {
      const fusion = JSON.parse(JSON.stringify(stage.$rankFusion)) as { input: { pipelines: Record<string, Doc[]> } };
      for (const name of Object.keys(fusion.input.pipelines)) {
        fusion.input.pipelines[name] = queryVectors(fusion.input.pipelines[name]);
      }
      return { ...stage, $rankFusion: fusion };
    }
    return stage;
  });
}

async function runAggregate(client: Client, database: string, collection: string, pipeline: Doc[], options?: Doc | null, session?: ClientSession): Promise<Doc[]> {
  try {
    const cursor = client.mongo.db(database).collection(collection).aggregate(bson(queryVectors(pipeline)) as Document[], { ...(options ?? {}), ...(session ? { session } : {}) });
    return (await cursor.toArray()) as Doc[];
  } catch (error) {
    throw failure(error, `aggregate on ${database}.${collection}`);
  }
}

/**
 * A pipeline; its documents as records (key first, score second), or the first document, or a member of it; with candidates, the
 * records unrounded for the shared result-shape module (see shape).
 */
export async function aggregate(client: Client, args: { database: string; collection: string; pipeline: Doc[]; key?: string; options?: Doc | null;
  first?: boolean; select?: string[]; default?: Json; candidates?: boolean }): Promise<Json> {
  const documents = (await runAggregate(client, args.database, args.collection, args.pipeline, args.options)).map((document) => record(document, args.key));
  if (args.candidates) {
    return value(documents, false);
  }
  if (!args.first) {
    return value(documents);
  }
  const result = documents.length > 0 ? select(documents[0], args.select) : null;
  return value(result === null || result === undefined ? (args.default ?? null) : result);
}

/** Creates the search index, or updates its definition when it exists. */
export async function ensureSearchIndex(client: Client, args: { database: string; collection: string; index: string; type: string; definition: Doc }): Promise<void> {
  const existing = await runAggregate(client, args.database, args.collection, [{ $listSearchIndexes: { name: args.index } }]);
  if (existing.length > 0) {
    await runCommand(client, args.database, { updateSearchIndex: args.collection, name: args.index, definition: args.definition });
  } else {
    await runCommand(client, args.database, { createSearchIndexes: args.collection, indexes: [{ name: args.index, type: args.type, definition: args.definition }] });
  }
}

function sleep(millis: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, millis));
}

/** The status of a search index once it is READY and queryable, or a clear error after timeout_seconds. */
export async function awaitIndex(client: Client, args: { database: string; collection: string; index: string; timeout_seconds: number }): Promise<string> {
  const deadline = Date.now() + args.timeout_seconds * 1000;
  let status = "missing";
  for (;;) {
    const found = await runAggregate(client, args.database, args.collection, [{ $listSearchIndexes: { name: args.index } }]);
    if (found.length > 0) {
      status = String(found[0].status ?? "UNKNOWN");
      if (status === "FAILED") {
        throw new MongodbFailure(`search index ${args.index} on ${args.database}.${args.collection} failed to build: ${String(found[0].message ?? "")}`);
      }
      if (status === "READY" && found[0].queryable === true) {
        return status;
      }
    }
    if (Date.now() >= deadline) {
      throw new Error(`search index ${args.index} on ${args.database}.${args.collection} was not queryable within ${args.timeout_seconds} seconds (status ${status})`);
    }
    await sleep(POLL_MILLIS);
  }
}

function probePipeline(probe: Probe, condition: Doc, limit: number): Doc[] {
  if (probe.kind === "vector") {
    const query = [1.0, ...new Array<number>(Number(probe.dims) - 1).fill(0.0)];
    return [{ $vectorSearch: { index: probe.index, path: probe.path, queryVector: query, exact: true, limit: Math.max(1, limit), filter: condition } }, { $count: "n" }];
  }
  const operator = "_id" in condition ? { in: { path: "_id", value: (condition._id as Doc).$in } } : { equals: { path: STAMP, value: (condition[STAMP] as Doc).$eq } };
  return [{ $search: { index: probe.index, ...operator } }, { $count: "n" }];
}

/** Waits until mongot shows the write in every search index: the stamped documents, or the deleted keys gone. */
async function visibleWrite(client: Client, database: string, collection: string, visible: Visible | null | undefined, stamp: string | null, deleted?: unknown[] | null): Promise<void> {
  if (!visible) {
    return;
  }
  const timeout = Number(visible.timeout_seconds);
  const deadline = Date.now() + timeout * 1000;
  for (const probe of visible.probes) {
    let condition: Doc;
    let expected = 0;
    if (deleted !== undefined && deleted !== null) {
      if (deleted.length === 0) {
        continue;
      }
      condition = { _id: { $in: deleted } };
    } else {
      condition = { [STAMP]: { $eq: stamp } };
      const stored: Doc = { ...condition };
      if (probe.kind === "vector") {
        stored[String(probe.path)] = { $type: "array" };
      }
      const counted = await runAggregate(client, database, collection, [{ $match: stored }, { $count: "n" }]);
      expected = counted.length > 0 ? Number(counted[0].n) : 0;
    }
    for (;;) {
      const found = await runAggregate(client, database, collection, probePipeline(probe, condition, Math.max(expected, deleted?.length ?? 0)));
      const count = found.length > 0 ? Number(found[0].n) : 0;
      if ((deleted && count === 0) || (!deleted && count >= expected)) {
        break;
      }
      if (Date.now() >= deadline) {
        throw new Error(`search index ${probe.index} of ${database}.${collection} did not show the write within ${timeout} seconds`);
      }
      await sleep(POLL_MILLIS);
    }
  }
}

type WriteArgs = { database: string; collection: string; records: Doc[]; key: string; op: string; counter: string; extra?: Doc | null; defaults?: Doc | null;
  vectors?: string[] | null; dates?: string[] | null; versioned?: boolean; ttl_seconds?: number | null; batch_size?: number; ignore_conflicts?: boolean;
  visible?: Visible | null; only?: unknown[] | null };

function documentsOf(args: WriteArgs, stamp: string): Doc[] {
  const expires = args.ttl_seconds !== undefined && args.ttl_seconds !== null ? new Date(Date.now() + args.ttl_seconds * 1000) : null;
  return args.records.map((source) => {
    if (!(args.key in source)) {
      throw new MongodbFailure(`a record without the key ${args.key}: ${JSON.stringify(source).slice(0, 200)}`);
    }
    const body: Doc = { ...(args.defaults ?? {}) };
    for (const [name, item] of Object.entries(source)) {
      if (name !== args.key) {
        body[name] = item;
      }
    }
    Object.assign(body, args.extra ?? {});
    const document: Doc = { _id: bson(source[args.key]), ...coerce(body, args.vectors, args.dates), [STAMP]: stamp };
    if (args.versioned) {
      document[VERSION] = 1;
    }
    if (expires !== null) {
      document[EXPIRES] = expires;
    }
    return document;
  });
}

async function writeDocuments(client: Client, args: WriteArgs, documents: Doc[], session?: ClientSession): Promise<[number, number]> {
  let written = 0;
  let skipped = 0;
  const concern: Doc = session ? {} : { writeConcern: { w: "majority" } };
  const size = args.batch_size ?? BATCH;
  for (let start = 0; start < documents.length; start += size) {
    const batch = documents.slice(start, start + size);
    let answer: Document;
    if (args.op === "insert") {
      answer = await runCommand(client, args.database, { insert: args.collection, documents: batch, ordered: !args.ignore_conflicts, ...concern }, session);
    } else if (args.op === "patch") {
      const updates = batch.map((document) => {
        const rest: Doc = {};
        for (const [name, item] of Object.entries(document)) {
          if (name !== "_id" && name !== VERSION) {
            rest[name] = item;
          }
        }
        return { q: { _id: { $eq: document._id } }, u: VERSION in document ? { $set: rest, $inc: { [VERSION]: 1 } } : { $set: rest }, upsert: false };
      });
      answer = await runCommand(client, args.database, { update: args.collection, updates, ordered: true, ...concern }, session);
    } else {
      const updates = batch.map((document) => {
        const rest: Doc = {};
        for (const [name, item] of Object.entries(document)) {
          if (name !== "_id") {
            rest[name] = item;
          }
        }
        return { q: { _id: { $eq: document._id } }, u: args.op === "merge" ? { $set: rest } : rest, upsert: true };
      });
      answer = await runCommand(client, args.database, { update: args.collection, updates, ordered: true, ...concern }, session);
    }
    for (const error of (answer.writeErrors ?? []) as Doc[]) {
      if (error.code === 11000 && args.ignore_conflicts) {
        skipped += 1;
      } else {
        throw new MongodbFailure(`${args.op} into ${args.database}.${args.collection} failed: ${String(error.code)}: ${String(error.errmsg)}`);
      }
    }
    written += Number(answer.n ?? 0);
  }
  return [written, skipped];
}

/**
 * Records written as insert commands (insert), or update commands with upsert: a replacement (replace) or $set (merge), or without
 * upsert (patch: $set on existing documents only; a missing document is not counted). With only, the records whose key is not among
 * those keys are left out.
 */
export async function write(client: Client, args: WriteArgs, session?: ClientSession): Promise<Doc> {
  const stamp = randomUUID().replace(/-/g, "");
  const keys = args.only === undefined || args.only === null ? null : new Set(args.only.map((value) => JSON.stringify(value)));
  const selected = keys === null ? args : { ...args, records: args.records.filter((record) => args.key in record && keys.has(JSON.stringify(record[args.key]))) };
  const [written, skipped] = await writeDocuments(client, selected, documentsOf(selected, stamp), session);
  if (skipped > 0 && !args.ignore_conflicts) {
    throw new MongodbFailure(`${skipped} records of the insert into ${args.database}.${args.collection} already exist`);
  }
  if (!session) {
    await visibleWrite(client, args.database, args.collection, args.visible, stamp);
  }
  const result: Doc = args.ignore_conflicts ? { [args.counter]: written, skipped } : { [args.counter]: written };
  return session ? { ...result, _stamp: stamp } : result;
}

/** An update command on every matching document; values are operands of $set, $unset, $push, $pull and $inc. */
export async function update(client: Client, args: { database: string; collection: string; filter: Doc; update: Doc; counter?: string; vectors?: string[] | null;
  dates?: string[] | null; visible?: Visible | null }, session?: ClientSession): Promise<Doc> {
  const stamp = randomUUID().replace(/-/g, "");
  const change: Doc = {};
  for (const [operator, fields] of Object.entries(args.update)) {
    change[operator] = { ...(fields as Doc) };
  }
  change.$set = { ...coerce((change.$set ?? {}) as Doc, args.vectors, args.dates), [STAMP]: stamp };
  const concern: Doc = session ? {} : { writeConcern: { w: "majority" } };
  const answer = await runCommand(client, args.database, { update: args.collection, updates: [{ q: args.filter, u: change, multi: true }], ...concern }, session);
  for (const error of (answer.writeErrors ?? []) as Doc[]) {
    throw new MongodbFailure(`update of ${args.database}.${args.collection} failed: ${String(error.code)}: ${String(error.errmsg)}`);
  }
  if (!session) {
    await visibleWrite(client, args.database, args.collection, args.visible, stamp);
  }
  const result: Doc = { [args.counter ?? "update_count"]: Number(answer.n ?? 0) };
  return session ? { ...result, _stamp: stamp } : result;
}

/** A delete command; a limit above 1 (or a wait for mongot) first reads the matching keys in key order. */
export async function delete_(client: Client, args: { database: string; collection: string; filter: Doc; limit?: number | null; visible?: Visible | null },
  session?: ClientSession): Promise<Doc> {
  let filter = args.filter;
  let keys: unknown[] | null = null;
  const limit = args.limit ?? null;
  if ((limit !== null && limit > 1) || args.visible) {
    const stages: Doc[] = [{ $match: filter }, { $sort: { _id: 1 } }];
    if (limit !== null) {
      stages.push({ $limit: limit });
    }
    stages.push({ $project: { _id: 1 } });
    keys = (await runAggregate(client, args.database, args.collection, stages, null, session)).map((document) => document._id);
    filter = { _id: { $in: keys } };
  }
  const concern: Doc = session ? {} : { writeConcern: { w: "majority" } };
  const answer = await runCommand(client, args.database, { delete: args.collection, deletes: [{ q: filter, limit: limit === 1 ? 1 : 0 }], ...concern }, session);
  if (!session) {
    await visibleWrite(client, args.database, args.collection, args.visible, null, keys);
  }
  const result: Doc = { delete_count: Number(answer.n ?? 0) };
  return session ? { ...result, _deleted: keys } : result;
}

export { delete_ as delete };

/** The steps' writes in one multi-document transaction (aborted on any error); waits for mongot after the commit. */
export async function transaction(client: Client, args: { steps: { op: string; args: Doc }[]; read_concern?: string }): Promise<Json> {
  const results: Doc[] = [];
  const session = client.mongo.startSession();
  try {
    session.startTransaction({ readConcern: { level: (args.read_concern ?? "snapshot") as "snapshot" }, writeConcern: { w: "majority" } });
    try {
      for (const step of args.steps) {
        if (step.op === "write") {
          results.push(await write(client, step.args as WriteArgs, session));
        } else if (step.op === "update") {
          results.push(await update(client, step.args as Parameters<typeof update>[1], session));
        } else {
          results.push(await delete_(client, step.args as Parameters<typeof delete_>[1], session));
        }
      }
      await session.commitTransaction();
    } catch (error) {
      if (session.inTransaction()) {
        await session.abortTransaction();
      }
      throw error;
    }
  } finally {
    await session.endSession();
  }
  for (let position = 0; position < args.steps.length; position += 1) {
    const step = args.steps[position];
    const result = results[position];
    const stamp = (result._stamp as string | undefined) ?? null;
    const deleted = (result._deleted as unknown[] | null | undefined) ?? null;
    delete result._stamp;
    delete result._deleted;
    const visible = step.args.visible as Visible | null | undefined;
    if (visible) {
      if (step.op === "delete") {
        await visibleWrite(client, String(step.args.database), String(step.args.collection), visible, null, deleted ?? []);
      } else {
        await visibleWrite(client, String(step.args.database), String(step.args.collection), visible, stamp);
      }
    }
  }
  return value(results);
}

/** Records of a local JSON array or JSON Lines file (file:// URI or path). */
export async function readRecords(_client: Client, args: { location: string }): Promise<Doc[]> {
  const path = args.location.startsWith("file://") ? args.location.slice("file://".length) : args.location;
  const text = readFileSync(path, "utf-8");
  if (text.trimStart().startsWith("[")) {
    return JSON.parse(text) as Doc[];
  }
  return text.split(/\r?\n/).filter((line) => line.trim() !== "").map((line) => JSON.parse(line) as Doc);
}

export async function importFile(client: Client, args: Omit<WriteArgs, "records" | "ttl_seconds" | "visible"> & { location: string }): Promise<Doc> {
  const records = await readRecords(client, { location: args.location });
  return write(client, { ...args, records });
}

/** Names: collections, views, databases, search indexes or the distinct values of a field. */
export async function names(client: Client, args: { kind: string; database: string; collection?: string; field?: string; prefix?: string; limit?: number }): Promise<string[]> {
  let found: string[];
  if (args.kind === "collections") {
    const answer = await runCommand(client, args.database, { listCollections: 1, filter: { type: "collection" }, nameOnly: true });
    found = (answer.cursor.firstBatch as Doc[]).map((entry) => String(entry.name)).filter((name) => !name.startsWith("system."));
  } else if (args.kind === "views") {
    const answer = await runCommand(client, args.database, { listCollections: 1, filter: { type: "view" } });
    found = (answer.cursor.firstBatch as Doc[]).filter((entry) => args.collection === undefined || (entry.options as Doc | undefined)?.viewOn === args.collection)
      .map((entry) => String(entry.name));
  } else if (args.kind === "databases") {
    const answer = await runCommand(client, "admin", { listDatabases: 1, nameOnly: true });
    found = (answer.databases as Doc[]).map((entry) => String(entry.name)).filter((name) => !["admin", "config", "local"].includes(name));
  } else if (args.kind === "search_indexes") {
    found = (await runAggregate(client, args.database, String(args.collection), [{ $listSearchIndexes: {} }])).map((entry) => String(entry.name));
  } else {
    const answer = await runCommand(client, args.database, { distinct: args.collection, key: args.field, query: {} });
    found = (answer.values as unknown[]).filter((item) => item !== null && item !== undefined).map((item) => String(value(item)));
  }
  let result = [...new Set(found)].sort();
  if (args.prefix !== undefined) {
    result = result.filter((name) => name.startsWith(args.prefix as string));
  }
  return args.limit !== undefined ? result.slice(0, args.limit) : result;
}

async function vectorsOf(client: Client, database: string, collection: string, field: string, values: unknown[]): Promise<number[][]> {
  if (values.length === 0) {
    return [];
  }
  const documents = await runAggregate(client, database, collection, [{ $match: { _id: { $in: values } } }, { $project: { [field]: 1 } }]);
  const found = new Map(documents.map((document) => [JSON.stringify(value(document._id)), document[field] as number[] | undefined]));
  return values.map((item) => {
    const vector = found.get(JSON.stringify(value(item)));
    if (vector === undefined || vector === null) {
      throw new MongodbFailure(`an example of the recommendation has no ${field} vector in ${database}.${collection}`);
    }
    return vector.map(Number);
  });
}

function average(vectors: number[][]): number[] {
  return vectors[0].map((_, column) => vectors.reduce((sum, vector) => sum + vector[column], 0) / vectors.length);
}

/**
 * Qdrant's average-vector strategy: avg(positive) + (avg(positive) - avg(negative)) as the queryVector of $vectorSearch; with
 * candidates, the records unrounded for the shared result-shape module (see shape).
 */
export async function recommend(client: Client, args: { database: string; collection: string; lookup: string; field: string; pipeline: Doc[]; key: string;
  options?: Doc | null; first?: boolean; positive_ids?: unknown[]; positive_vectors?: number[][]; negative_ids?: unknown[]; negative_vectors?: number[][];
  candidates?: boolean }): Promise<Json> {
  const positives = [...(await vectorsOf(client, args.database, args.lookup, args.field, args.positive_ids ?? [])), ...(args.positive_vectors ?? [])];
  const negatives = [...(await vectorsOf(client, args.database, args.lookup, args.field, args.negative_ids ?? [])), ...(args.negative_vectors ?? [])];
  let query = average(positives);
  if (negatives.length > 0) {
    const avoid = average(negatives);
    query = query.map((item, position) => 2 * item - avoid[position]);
  }
  const documents = (await runAggregate(client, args.database, args.collection, queryVectors(args.pipeline, query), args.options)).map((document) => record(document, args.key));
  if (args.candidates) {
    return value(documents, false);
  }
  return value(args.first && documents.length > 0 ? documents[0] : documents);
}

function order(left: Doc, right: Doc, key: string): number {
  const scoreOrder = (right.score as number) - (left.score as number);
  if (scoreOrder !== 0) {
    return scoreOrder;
  }
  const a = left[key];
  const b = right[key];
  if (typeof a === "number" && typeof b === "number") {
    return a - b;
  }
  if (typeof a === "number") {
    return -1;
  }
  if (typeof b === "number") {
    return 1;
  }
  return String(a) < String(b) ? -1 : String(a) > String(b) ? 1 : 0;
}

function within(score: number, bounds?: Bounds | null): boolean {
  if (!bounds) {
    return true;
  }
  return (bounds.min === undefined || score >= bounds.min - 1e-9) && (bounds.max === undefined || score <= bounds.max + 1e-9);
}

/** Fusion of the legs' records: rrf sums 1/(k + rank), weighted sums weight * similarity, relative_score sums the
 * weighted min-max normalized similarities; ties by key. With candidates, the fused records come back unrounded for the shared
 * result-shape module (see shape). */
export async function hybrid(client: Client, args: { database: string; collection: string; legs: { pipeline: Doc[]; weight: number }[]; fusion: string; k: number;
  size: number; offset: number; key: string; bounds?: Bounds | null; candidates?: boolean }): Promise<Json> {
  const fused = new Map<string, Doc>();
  const rounded = !args.candidates;
  for (const leg of args.legs) {
    const hits = (await runAggregate(client, args.database, args.collection, leg.pipeline)).map((document) => record(value(document, rounded) as Doc, args.key));
    const scores = hits.map((hit) => hit.score as number);
    const low = scores.length > 0 ? Math.min(...scores) : 0;
    const high = scores.length > 0 ? Math.max(...scores) : 0;
    hits.forEach((hit, position) => {
      const rank = position + 1;
      const score = hit.score as number;
      const part = args.fusion === "rrf" ? 1 / (args.k + rank)
        : args.fusion === "relative_score" ? leg.weight * (high > low ? (score - low) / (high - low) : 1.0) : leg.weight * score;
      const id = JSON.stringify(hit[args.key]);
      let entry = fused.get(id);
      if (entry === undefined) {
        entry = { ...hit, score: 0 };
        fused.set(id, entry);
      }
      entry.score = (entry.score as number) + part;
    });
  }
  const ranked = [...fused.values()].filter((entry) => within(entry.score as number, args.bounds)).sort((left, right) => order(left, right, args.key));
  return value(ranked.slice(args.offset, args.offset + args.size).map((entry) => record(entry, args.key)), rounded);
}

/**
 * The result-shape clauses over a candidate window, by the shared module vecdslShapes: each record becomes a candidate {key,
 * score, fields, vectors, highlight, explanation} (its highlights as the highlight); the vector fields the candidates carry go
 * to vectors and stay among the fields only where the output names them.
 */
export async function shape(_client: Client, args: { candidates: Json; spec: Doc; vectors: string[] }): Promise<Json> {
  const key = args.spec.keyField as string;
  const listed = new Set(Array.isArray(args.spec.output) ? (args.spec.output as string[]) : []);
  const items = (args.candidates as Doc[]).map((item) => {
    const fields: Doc = {};
    for (const [name, entry] of Object.entries(item)) {
      if (name !== key && name !== "score" && name !== "highlights" && name !== "explanation" && (!args.vectors.includes(name) || listed.has(name))) {
        fields[name] = entry;
      }
    }
    const vectors: Doc = {};
    for (const name of args.vectors) {
      if (name in item) {
        vectors[name] = item[name];
      }
    }
    const candidate: Doc = { key: item[key], score: item.score ?? null, fields, vectors };
    if ("highlights" in item) {
      candidate.highlight = item.highlights;
    }
    if ("explanation" in item) {
      candidate.explanation = item.explanation;
    }
    return candidate as Shapeable;
  });
  try {
    return shapeCandidates(items, args.spec as { [key: string]: Shapeable });
  } catch (error) {
    if (error instanceof UnsupportedShape) {
      unsupported("mongodb", error.message);
    }
    throw error;
  }
}

export { MongoError };
